const text = ($input.first().json.message.text || '').toLowerCase();
const chatId = $input.first().json.message.chat.id;
let reply = 'Comando no reconocido. Usa /help';
if (text === '/start') reply = 'Bienvenido al bot 👋';
else if (text === '/help') reply = 'Comandos: /start, /hora, /help';
else if (text === '/hora') reply = 'Hora: ' + new Date().toLocaleString('es-ES');
return [{ json: { chatId, reply } }];
